import { AtlasAttachmentLoader, SkeletonJson, Spine, TextureAtlas } from '@pixi/spine-pixi';
import * as PIXI from 'pixi.js';
export type AssetData = {
    alias: string;
    spritePath: string;
    jsonPath?: string;
};
export type SpineAssetData = {
    alias: string;
    skeletonPath: string;
    atlasPath: string;
};
type RegisteredAssetData = AssetData | SpineAssetData;

export class AssetLoader {

    private static readonly PRELOAD_ASSETS: RegisteredAssetData[] = [];
    private static readonly INIT_ASSETS: RegisteredAssetData[] = [];
    private static readonly LAZY_ASSETS: RegisteredAssetData[] = [];

    public static getBaseUrl(): string {
        const base = import.meta.env?.BASE_URL ?? '/';
        return base.endsWith('/') ? base : `${base}/`;
    }

    public static getAssetUrl(relativePath: string): string {
        const path = (relativePath ?? '').trim();
        if (/^(?:[a-z]+:)?\/\//i.test(path) || path.startsWith('data:')) {
            return path;
        }

        const baseUrl = this.getBaseUrl();
        const basePath = baseUrl.replace(/^\/+|\/+$/g, '');
        let normalizedPath = path.replace(/^\/+/, '');
        if (basePath && normalizedPath.startsWith(`${basePath}/`)) {
            normalizedPath = normalizedPath.slice(basePath.length).replace(/^\/+/, '');
        }

        return new URL(normalizedPath, window.location.origin + baseUrl).toString();
    }

    public static load(alias: string, spritePath: string, jsonPath?: string, loadType: 'init' | 'lazy' | 'preload' = 'init'): void {
        switch (loadType) {
            case 'init':
                this.INIT_ASSETS.push({ alias, spritePath, jsonPath });
                break;
            case 'lazy':
                this.LAZY_ASSETS.push({ alias, spritePath, jsonPath });
                break;
            case 'preload':
                this.PRELOAD_ASSETS.push({ alias, spritePath, jsonPath });
                break;
            default:
                throw new Error(`Invalid loadType: ${loadType}`);
        }
    }
    public static loadSpine(alias: string, skeletonPath: string, atlasPath: string, loadType: 'init' | 'lazy' | 'preload' = 'init'): void {
        const asset: SpineAssetData = { alias, skeletonPath, atlasPath };
        switch (loadType) {
            case 'init':
                this.INIT_ASSETS.push(asset);
                break;
            case 'lazy':
                this.LAZY_ASSETS.push(asset);
                break;
            case 'preload':
                this.PRELOAD_ASSETS.push(asset);
                break;
            default:
                throw new Error(`Invalid loadType: ${loadType}`);
        }
    }

    public static async loadAssets(onProgress?: (progress: number) => void): Promise<void> {
        onProgress?.(0);

        for (let i = 0; i < this.INIT_ASSETS.length; i += 1) {
            const asset = this.INIT_ASSETS[i];

            try {
                if ('skeletonPath' in asset) {
                    const skeletonAlias = `${asset.alias}-skeleton`;
                    const atlasAlias = `${asset.alias}-atlas`;
                    PIXI.Assets.add({ alias: skeletonAlias, src: this.getAssetUrl(asset.skeletonPath) });
                    PIXI.Assets.add({ alias: atlasAlias, src: this.getAssetUrl(asset.atlasPath) });
                    await PIXI.Assets.load([skeletonAlias, atlasAlias]);
                } else {
                    PIXI.Assets.add({ alias: asset.alias, src: asset.jsonPath });
                    await PIXI.Assets.load([asset.alias, asset.spritePath]);
                }

            } catch (error) {
                console.warn(`[AssetManifest] Failed to load "${asset.alias}".`, error);
            }

            onProgress?.((i + 1) / this.INIT_ASSETS.length);
        }
    }

    public static getSpine(alias: string): Spine | null {
    try {
        const skeletonAlias = `${alias}-skeleton`;
        const atlasAlias = `${alias}-atlas`;

        const rawJson = PIXI.Assets.get(skeletonAlias);
        const atlasAsset = PIXI.Assets.get(atlasAlias);

        if (!rawJson || !atlasAsset) {
            console.error(`[AssetLoader] Assets not found for alias: ${alias}`);
            return null;
        }

        let atlas: TextureAtlas;

        // Check karein ki atlasAsset raw string hai ya spine plugin dwara parsed object
        if (typeof atlasAsset === "string") {
            atlas = new TextureAtlas(atlasAsset);
            for (const page of atlas.pages) {
                const texture = PIXI.Assets.get(page.name) || PIXI.Assets.get(`${alias}-image`);
                if (texture) {
                    page.setTexture(texture);
                }
            }
        } else {
            // Agar spine-pixi ne ise pehle hi TextureAtlas bana diya hai
            atlas = atlasAsset as unknown as TextureAtlas;
        }

        // Skeleton data parse karke Spine object banayein
        const atlasLoader = new AtlasAttachmentLoader(atlas);
        const skeletonJson = new SkeletonJson(atlasLoader);
        const skeletonData = skeletonJson.readSkeletonData(rawJson);

        const spineAnimation = new Spine(skeletonData);
        return spineAnimation;

    } catch (error) {
        console.error(`[AssetLoader] Failed to create spine for alias "${alias}":`, error);
        return null;
    }
}

    public static getTexture(alias: string, frameName: string): PIXI.Texture {
        const loadedTexture = PIXI.Assets.get(alias);

        if (loadedTexture) {
            const singleTexture = loadedTexture.textures[frameName] || loadedTexture;
            return singleTexture;
        }
        return PIXI.Texture.WHITE;
    }
}